import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Lock, Chrome } from 'lucide-react';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    // For now, we'll just navigate to the home page
    // In a real app, you'd validate credentials here
    if (username && password) {
      navigate('/home');
    } else {
      alert("Please enter both username and password");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f0f2f5]">
      <div className="bg-white p-10 rounded-2xl shadow-xl w-full max-w-md border border-gray-100">
        
        {/* Logo and Header */}
        <div className="flex flex-col items-center mb-8">
          <div className="bg-gray-800 p-3 rounded-full mb-3">
             <User className="text-white" size={28} />
          </div>
          <h2 className="text-2xl font-bold text-gray-800">Talent Pool</h2>
          <p className="text-[#7c5dfa] font-medium mt-2">Hi, Welcome Back!</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          {/* Username Input */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Username</label>
            <div className="relative">
              <input 
                type="text" 
                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-400 outline-none transition-all"
                placeholder="Enter your username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>
          </div>

          {/* Password Input */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Password</label>
            <div className="relative">
              <input 
                type="password" 
                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-purple-400 outline-none transition-all"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
          </div>

          {/* Login Button */}
          <button 
            type="submit"
            className="w-full bg-[#7c5dfa] hover:bg-[#6a4dec] text-white font-bold py-3 rounded-lg shadow-lg transform active:scale-95 transition-all"
          >
            Login
          </button>
        </form>

        <div className="relative my-8 text-center">
          <hr className="border-gray-200" />
          <span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-4 text-gray-400 text-sm">Or</span>
        </div>

        {/* Google Sign In */}
        <button className="w-full flex items-center justify-center gap-3 border border-gray-300 py-3 rounded-lg hover:bg-gray-50 transition-all text-gray-700 font-medium">
          <Chrome size={20} className="text-red-500" />
          Sign in with Google
        </button>
      </div>
    </div>
  );
};

export default Login;
